function buildPlan(){const plan=[];plan.push({kind:'root',id:DATA.page.root_key,name:DATA.page.root_name,x:0,y:0,width:DATA.page.width,height:DATA.page.height,parent:'page'});plan.push({kind:'header',id:'atlas.header.instance',name:'ATLAS_PAGE_HEADER_V2 · Owner Review Index',x:64,y:64,width:2496,height:128,parent:'root'});const columns=[['ORDER',64,72],['REVIEW KEY',148,720],['PACKAGE',900,430],['SUBJECT',1348,480],['VIEWPORT / SCENARIO',1848,430],['STATE',2296,264]];for(const [label,x,width] of columns)plan.push(textPlan('column/'+label.toLowerCase().replaceAll(' ','-').replaceAll('/','-'),label,x,220,width,24,11,'700','#4B5563'));for(const group of DATA.group_order){plan.push(textPlan('group/'+group,group,64,groupY(group)+6,1200,22,11,'700','#374151'));}for(let index=0;index<DATA.rows.length;index+=1){const row=DATA.rows[index];const y=rowY(index);const shade=index%2===0?'#FFFFFF':'#F8FAFC';plan.push({kind:'rect',id:'row/'+String(index+1).padStart(2,'0'),name:'Owner review row '+String(row.order),x:64,y,width:2496,height:48,color:shade,parent:'root',row});plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/order',String(row.order).padStart(2,'0'),76,y+14,56,20,10,'700'));plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/review-key',row.review_key,148,y+14,720,20,10,'400'));plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/package',row.package_id,900,y+14,430,20,10,'400'));plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/subject',row.subject,1348,y+14,480,20,10,'400'));plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/viewport-scenario',row.viewport+' · '+row.scenario,1848,y+14,430,20,10,'400','#4B5563'));plan.push(textPlan('row/'+String(index+1).padStart(2,'0')+'/state',row.v0_acceptance,2296,y+14,264,20,10,'700','#92400E'));}plan.push(textPlan('legend/pending','PENDING · Every case remains unaccepted until page-scoped V0 review',64,DATA.page.height-48,1200,24,11,'700','#92400E'));return plan}
